public sealed class ReplayShowcaseState
{
    public string Phase = "Step 1 — [Nudge hero] a few times, then [Start record] and nudge more";
    public string Status = "Ready.";
    public bool IsRecording;
    public bool IsReplaying;
    public bool IsPaused;
    public int Frames;
    public int PlaybackIndex = -1;
    public int CurrentTick;
    public string RecordedEndDigest = "-";
    public string PlaybackDigest = "-";
    public bool EndMatches;
    public string ArchiveLine = "no archive yet";
    public string IsolationNote = "n/a";
    public IReadOnlyList<string> LogLines = Array.Empty<string>();

    public bool Equals(ReplayShowcaseState? other)
    {
        if (other == null || LogLines.Count != other.LogLines.Count) return false;
        for (int i = 0; i < LogLines.Count; i++)
        {
            if (LogLines[i] != other.LogLines[i]) return false;
        }

        return Phase == other.Phase && Status == other.Status && IsRecording == other.IsRecording &&
            IsReplaying == other.IsReplaying && IsPaused == other.IsPaused && Frames == other.Frames &&
            PlaybackIndex == other.PlaybackIndex && CurrentTick == other.CurrentTick &&
            RecordedEndDigest == other.RecordedEndDigest && PlaybackDigest == other.PlaybackDigest &&
            EndMatches == other.EndMatches && ArchiveLine == other.ArchiveLine && IsolationNote == other.IsolationNote;
    }
}

/// <summary>
/// Deterministic replay showcase: nudges inject real authoritative input actions (Command order),
/// the recorder captures every frame, and ReplayPlayer replays them from the recorded checkpoint
/// through the same pipeline. The visible proof: recorded-end digest == post-replay digest, and live
/// input during playback is isolated. Archives round-trip through disk for cold-session replay.
/// </summary>
public sealed class ReplayPlaybackRuntime
{
    private readonly GameEngine _engine;
    private readonly List<string> _log = new(10);
    private readonly List<AuthoritativeAction> _frameActions = new(8);
    private ReplayRecorder? _recorder;
    private ReplayArchive? _archive;
    private bool _replayPlaying;
    private bool _replayPaused;
    private bool _replayFrameQueued;
    private int _replayIndex;
    private int _replayFrames;
    private string? _recordedEndDigest;
    private string? _playbackEndDigest;
    private string? _liveRejectedSample;
    private long _nextSequence = 0;

    public ReplayPlaybackRuntime(GameEngine engine)
    {
        _engine = engine ?? throw new ArgumentNullException(nameof(engine));
    }

    public bool IsShowcaseMap => DeterministicReplayShowcaseIds.MapId == _engine.CurrentMapSession?.MapId.Value;
    public bool IsRecording => _recorder != null;
    public bool IsReplaying => _replayPlaying;

    public const string NudgeActionId = "DeterministicReplayShowcase.Nudge";

    public void NudgeHero()
    {
        if (_engine.GetService(CoreServiceKeys.AuthoritativeInputAccumulator) is not Ludots.Core.Input.Runtime.AuthoritativeInputAccumulator accumulator) return;
        if (_replayPlaying)
        {
            _liveRejectedSample = NudgeActionId;
            Log("Live input during replay: isolated — playback frames stay authoritative.");
            return;
        }

        accumulator.CaptureAction(NudgeActionId, new Vector3(6400 + RandomShared(-800, 800), 0, 6400 + RandomShared(-800, 800)), true, true, false);
        Log("Nudge captured as an authoritative action — it enters the frame stream and drives the hero on the next fixed step.");
    }

    internal bool StartRequested { get; set; }
    internal bool StopRequested { get; set; }

    public void StartRecording()
    {
        if (_replayPlaying) { Log("Stop the replay before recording."); return; }
        StartRequested = true;
        Log("Recording requested — starts at the next fixed-step boundary.");
    }

    internal void BeginRecordingAtFixedBoundary()
    {
        StartRequested = false;
        if (_recorder != null) return;
        _nextSequence = 0;
        _recorder = new ReplayRecorder();
        _recorder.SetCheckpoint(new WorldSnapshotService().Capture(
            _engine, SaveSnapshotBoundary.CleanAfter(SystemGroup.ClearPresentationFlags)));
        _recordedEndDigest = null;
        Log($"Recording from tick {_engine.GameSession.CurrentTick} — nudge now; every authoritative frame is captured.");
        Phase = "Step 2 — [Stop record] then [Play replay] to watch the same evolution again";
    }

    public void StopRecording()
    {
        if (_recorder == null && !StopRequested) { Log("Not recording."); return; }
        StopRequested = true;
        Log("Stop requested — settles at the next fixed-step boundary.");
    }

    internal void FinishRecordingAtFixedBoundary()
    {
        StopRequested = false;
        if (_recorder == null) return;
        _archive = _recorder.BuildArchive();
        _recorder = null;
        _recordedEndDigest = WorldDigest();
        Log($"Stopped: {_archive.Frames.Count} frames; end digest {_recordedEndDigest}.");
        Phase = "Step 3 — [Play replay]: frames drive the world from the recorded checkpoint";
    }

    public void PlayReplay()
    {
        if (_recorder != null) { Log("Stop recording first."); return; }
        if (_archive == null) { Log("No archive: record first (or [Load latest archive])."); return; }
        try
        {
            new ReplayPlayer(_archive.Validate()).PlayFromCheckpoint(_engine, new WorldRestoreService(), _ => { });
            _replayPlaying = true;
            _replayPaused = false;
            _replayIndex = 0;
            _replayFrames = 0;
            _playbackEndDigest = null;
            if (_engine.GetService(CoreServiceKeys.AuthoritativeInput) is FrozenInputActionReader replayInput)
            {
                replayInput.SetReplayInputIsolation(true);
            }

            QueueNextFrame();
            Log($"Replay started from checkpoint; live input isolated.");
            Phase = "Step 4 — compare the digests; then [Save archive] and replay it after a restart";
        }
        catch (Exception ex)
        {
            _replayPlaying = false;
            Log($"Replay rejected: {ex.Message}");
        }
    }

    public void TogglePause()
    {
        if (!_replayPlaying) return;
        _replayPaused = !_replayPaused;
        Log(_replayPaused ? "Paused — [Step one frame] walks tick by tick." : "Resumed.");
    }

    public void StepOne()
    {
        if (!_replayPlaying || !_replayPaused) { Log("Pause first, then step."); return; }
        if (!_replayFrameQueued) QueueNextFrame();
        if (_replayFrameQueued) { _replayFrames++; _replayIndex++; _replayFrameQueued = false; QueueNextFrame(); }
    }

    public void ResetReplay()
    {
        if (!_replayPlaying) return;
        _replayPlaying = false;
        _replayPaused = false;
        if (_engine.GetService(CoreServiceKeys.AuthoritativeInput) is FrozenInputActionReader input)
        {
            input.SetReplayInputIsolation(false);
            input.ClearReplayActions();
        }

        Log("Replay reset — the world stays where the replay left it.");
    }

    public void SaveArchive()
    {
        if (_archive == null) { Log("Nothing to archive."); return; }
        Directory.CreateDirectory(ArchiveDir);
        string path = LatestArchivePath(preferNew: true);
        File.WriteAllBytes(path, new ReplayArchiveCodec().Encode(_archive));
        Log($"Archive written: {path} — relaunch cold and [Load latest archive].");
    }

    public void LoadLatestArchive()
    {
        if (_replayPlaying || _recorder != null) { Log("Stop record/replay first."); return; }
        string[] files = Directory.Exists(ArchiveDir) ? Directory.GetFiles(ArchiveDir, "*.ludotsreplay") : Array.Empty<string>();
        if (files.Length == 0) { Log("No archives on disk yet."); return; }
        Array.Sort(files, StringComparer.Ordinal);
        _archive = new ReplayArchiveCodec().Decode(File.ReadAllBytes(files[^1])).Validate();
        _recordedEndDigest = null;
        Log($"Cold archive loaded: {files[^1]} — [Play replay] now runs it.");
    }

    public void AdvanceReplayFixedStep()
    {
        if (!_replayPlaying || _replayPaused || !_replayFrameQueued) return;
        _replayFrames++;
        _replayIndex++;
        _replayFrameQueued = false;
        QueueNextFrame();
    }

    public void ConsumeNudgeAction()
    {
        if (_engine.GetService(CoreServiceKeys.AuthoritativeInput) is not FrozenInputActionReader input) return;
        if (!input.PressedThisFrame(NudgeActionId)) return;
        Vector3 target = input.ReadAction<Vector3>(NudgeActionId);
        ApplyNudge((int)target.X, (int)target.Z);
    }

    private void ApplyNudge(int xCm, int yCm)
    {
        if (FindHero() is not { } hero) return;
        ref var pos = ref _engine.World.Get<Ludots.Core.Components.WorldPositionCm>(hero);
        pos = Ludots.Core.Components.WorldPositionCm.FromCm(xCm, yCm);
    }

    public void CaptureRecordingFrame()
    {
        if (_recorder == null || _replayPlaying) return;
        if (_engine.GetService(CoreServiceKeys.AuthoritativeInput) is not FrozenInputActionReader input) return;
        _frameActions.Clear();
        input.CopyAuthoritativeActions(_frameActions);
        _recorder.Record(new AuthoritativeFrame(_nextSequence++, _engine.GameSession.CurrentTick, _frameActions.ToArray()));
    }

    public string WorldDigest() => SaveWorldStateDigest.Compute(_engine)[..12];

    public string Phase { get; private set; } = "Step 1 — [Nudge hero] a few times, then [Start record] and nudge more";

    public ReplayShowcaseState BuildState() => new()
    {
        Phase = Phase,
        IsRecording = IsRecording,
        IsReplaying = _replayPlaying,
        IsPaused = _replayPaused,
        Frames = _recorder?.FrameCount ?? _archive?.Frames.Count ?? 0,
        PlaybackIndex = _replayPlaying ? _replayIndex : -1,
        CurrentTick = _engine.GameSession.CurrentTick,
        RecordedEndDigest = _recordedEndDigest ?? "-",
        PlaybackDigest = _playbackEndDigest ?? "-",
        EndMatches = _recordedEndDigest != null && _playbackEndDigest != null && _playbackEndDigest == _recordedEndDigest,
        ArchiveLine = _archive == null ? "no archive yet" : $"{_archive.Frames.Count} frames",
        IsolationNote = _liveRejectedSample == null
            ? (_replayPlaying ? "try [Nudge hero] now — live input is rejected" : "n/a")
            : $"last live input '{_liveRejectedSample}' → rejected",
        LogLines = _log.ToArray(),
    };

    private void QueueNextFrame()
    {
        if (!_replayPlaying || _replayIndex >= (_archive?.Frames.Count ?? 0))
        {
            _replayPlaying = false;
            if (_engine.GetService(CoreServiceKeys.AuthoritativeInput) is FrozenInputActionReader endedInput)
            {
                endedInput.SetReplayInputIsolation(false);
            }

            string digest = WorldDigest();
            _playbackEndDigest = digest;
            bool matches = _recordedEndDigest != null && digest == _recordedEndDigest;
            Log($"Replay finished {_replayFrames}/{_archive?.Frames.Count ?? 0} frames; digest {digest} " +
                (matches ? "== recorded end — deterministic" : $"MISMATCH vs {_recordedEndDigest}"));
            return;
        }

        if (_engine.GetService(CoreServiceKeys.AuthoritativeInput) is FrozenInputActionReader input)
        {
            input.QueueReplayActions(_archive!.Frames[_replayIndex].Actions);
            _replayFrameQueued = true;
        }
    }

    private Arch.Core.Entity? FindHero()
    {
        Arch.Core.Entity found = Arch.Core.Entity.Null;
        var query = new Arch.Core.QueryDescription().WithAll<Ludots.Core.Components.Name, Ludots.Core.Components.WorldPositionCm>();
        _engine.World.Query(in query, (Arch.Core.Entity e, ref Ludots.Core.Components.Name name) =>
        {
            if (name.Value == DeterministicReplayShowcaseIds.HeroName) found = e;
        });
        return found == Arch.Core.Entity.Null ? null : found;
    }

    private static string ArchiveDir => Path.Combine(AppContext.BaseDirectory, "Saves", "replay-showcase");

    private static string LatestArchivePath(bool preferNew) => Path.Combine(
        ArchiveDir,
        $"replay-{DateTime.UtcNow:yyyyMMdd-HHmmss}{(preferNew ? "" : "")}.ludotsreplay");

    private static int RandomShared(int min, int max) => Random.Shared.Next(min, max + 1);

    private void Log(string line)
    {
        _log.Insert(0, $"[replay] {line}");
        if (_log.Count > 8) _log.RemoveAt(_log.Count - 1);
    }
}

using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Arch.Core;
using Arch.System;
using Ludots.Core.Engine;
using Ludots.Core.Modding;
using Ludots.Core.Scripting;
using Ludots.UI;
using Ludots.UI.Compose;
using Ludots.UI.Reactive;
using Ludots.UI.Runtime;
using Ludots.UI.Surface;
using DeterministicReplayShowcaseMod.Runtime;

namespace DeterministicReplayShowcaseMod;

internal sealed class ReplayShowcaseInputSystem : BaseSystem<World, float>
{
    private readonly ReplayPlaybackRuntime _runtime;
    public ReplayShowcaseInputSystem(GameEngine engine, ReplayPlaybackRuntime runtime) : base(engine.World) { _runtime = runtime; }
    public override void Update(in float dt)
    {
        if (!_runtime.IsShowcaseMap) return;
        if (_runtime.IsReplaying)
        {
            _runtime.ConsumeNudgeAction();
            _runtime.AdvanceReplayFixedStep();
            return;
        }

        if (_runtime.StopRequested)
        {
            _runtime.FinishRecordingAtFixedBoundary();
            return;
        }

        if (_runtime.StartRequested)
        {
            _runtime.BeginRecordingAtFixedBoundary();
        }

        _runtime.ConsumeNudgeAction();
        _runtime.CaptureRecordingFrame();
    }
}

internal sealed class ReplayShowcasePresentationSystem : BaseSystem<World, float>
{
    private readonly GameEngine _engine;
    private readonly ReplayPlaybackRuntime _runtime;
    private readonly ReplayPanelController _panel;

    public ReplayShowcasePresentationSystem(GameEngine engine, ReplayPlaybackRuntime runtime) : base(engine.World)
    {
        _engine = engine;
        _runtime = runtime;
        _panel = new ReplayPanelController(runtime);
    }

    public override void Update(in float dt)
    {
        if (!_runtime.IsShowcaseMap) { _panel.ClearIfOwned(); return; }
        _panel.MountOrRefresh(_engine);
    }
}

internal sealed class ReplayPanelController
{
    private readonly ReplayPlaybackRuntime _runtime;
    private ReactivePage<ReplayShowcaseState>? _page;
    private GameEngine? _engine;
    private UiSurfaceLeaseHandle _lease;

    public ReplayPanelController(ReplayPlaybackRuntime runtime) => _runtime = runtime;

    public void MountOrRefresh(GameEngine engine)
    {
        if (engine.GetService(CoreServiceKeys.UiSurfaceHost) is not IUiSurfaceHost host) return;
        _engine = engine;
        ReplayShowcaseState state = _runtime.BuildState();
        if (_page == null)
        {
            var text = (IUiTextMeasurer)engine.GetService(CoreServiceKeys.UiTextMeasurer);
            var images = (IUiImageSizeProvider)engine.GetService(CoreServiceKeys.UiImageSizeProvider);
            _page = new ReactivePage<ReplayShowcaseState>(text, images, state, BuildRoot);
        }
        else if (!_page.State.Equals(state)) _page.SetState(_ => state);
        host.PublishReactivePage(ref _lease, new UiSurfaceLeaseRequest("DeterministicReplayShowcase.Panel", UiSurfaceSegment.Overlay, priority: 55), _page);
    }

    public void ClearIfOwned()
    {
        if (_lease.IsValid && _engine?.GetService(CoreServiceKeys.UiSurfaceHost) is IUiSurfaceHost host) host.ReleaseLease(ref _lease);
        _engine = null;
    }

    private UiElementBuilder BuildRoot(ReactiveContext<ReplayShowcaseState> context)
    {
        ReplayShowcaseState state = context.State;
        string digestColor = state.EndMatches ? "#8DE3AE" : "#F0C36B";
        return Ui.Column(
            Ui.Column(
                Ui.Text("Deterministic Replay — same inputs, same world").FontSize(20f).Bold().Color("#F5F7FA"),
                Ui.Text("Record authoritative input frames while you command the hero, then replay them: the world re-evolves identically from the recorded checkpoint, and live input during playback is rejected.")
                    .FontSize(11f).Color("#D6E0EA").WhiteSpace(UiWhiteSpace.Normal),
                Ui.Text(state.Phase).FontSize(12f).Bold().Color("#8AD7FF").WhiteSpace(UiWhiteSpace.Normal),
                Ui.Row(
                    Btn("Nudge hero", "nudge", r => r.NudgeHero()),
                    Btn("Start record", "record", r => r.StartRecording()),
                    Btn("Stop record", "stop", r => r.StopRecording()),
                    Btn("Play replay", "play", r => r.PlayReplay()),
                    Btn("Pause / Resume", "pause", r => r.TogglePause()),
                    Btn("Step one frame", "step", r => r.StepOne()),
                    Btn("Reset replay", "reset", r => r.ResetReplay()),
                    Btn("Save archive", "save", r => r.SaveArchive()),
                    Btn("Load latest archive", "load", r => r.LoadLatestArchive())).Gap(6f).Wrap(),
                Section("Determinism proof", new[]
                {
                    $"recorded end digest  {state.RecordedEndDigest}",
                    $"playback digest      {state.PlaybackDigest}",
                    state.EndMatches ? "MATCH — the replay reproduced the recorded end state" : "pending: play the replay to the end, then compare",
                    $"input isolation: {state.IsolationNote}",
                }, digestColor),
                Section("Live state", new[]
                {
                    $"tick {state.CurrentTick}   frames {state.Frames}   playback index {state.PlaybackIndex}",
                    $"recording {state.IsRecording}   replaying {state.IsReplaying}   paused {state.IsPaused}",
                    $"archive {state.ArchiveLine}",
                }, "#8DE3AE"),
                Section("Trace", state.LogLines, "#FFB38A"))
            .Width(560f).Padding(14f).Gap(8f).Radius(8f).Background("#0B1520").Border(1f, Color("#2F475E")))
            .WidthPercent(100f).HeightPercent(100f).Padding(16f).Align(UiAlignItems.Start).ZIndex(55);
    }

    private UiElementBuilder Btn(string label, string id, Action<ReplayPlaybackRuntime> action)
        => Ui.Button(label, _ => action(_runtime)).Id($"replay-show-{id}").Height(30f);

    private static UiElementBuilder Section(string title, IReadOnlyList<string> lines, string accent)
    {
        var children = new List<UiElementBuilder> { Ui.Text(title).FontSize(12f).Bold().Color(accent) };
        for (int i = 0; i < lines.Count; i++) children.Add(Ui.Text(lines[i]).FontSize(11f).Color(i == 0 ? "#F5F7FA" : "#C7D0DD").WhiteSpace(UiWhiteSpace.Normal));
        return Ui.Column(children.ToArray()).Width(520f).Padding(10f).Gap(5f).Background("#0E1823").Border(1f, Color("#284154"));
    }

    private static UiColor Color(string hex) => UiColor.TryParse(hex, out UiColor color) ? color : throw new InvalidOperationException($"Unsupported color '{hex}'.");
}

public sealed class DeterministicReplayShowcaseModEntry : IMod
{
    public void OnLoad(IModContext context)
    {
        var runtimeHolder = new ReplayPlaybackRuntime?[] { null };
        context.OnEvent(GameEvents.GameStart, ctx =>
        {
            if (ctx.Get(CoreServiceKeys.Engine) is not GameEngine engine ||
                (engine.GlobalContext.TryGetValue(DeterministicReplayShowcaseIds.InstalledKey, out object? value) && value is true))
            {
                return Task.CompletedTask;
            }

            engine.GlobalContext[DeterministicReplayShowcaseIds.InstalledKey] = true;
            var runtime = runtimeHolder[0] ??= new ReplayPlaybackRuntime(engine);
            engine.GlobalContext[DeterministicReplayShowcaseIds.RuntimeKey] = runtime;
            engine.RegisterSystem(new ReplayShowcaseInputSystem(engine, runtime), SystemGroup.InputCollection);
            engine.RegisterPresentationSystem(new ReplayShowcasePresentationSystem(engine, runtime));
            context.Log("[DeterministicReplayShowcaseMod] Deterministic replay showcase installed.");
            return Task.CompletedTask;
        });
    }

    public void OnUnload()
    {
    }
}

using System.Linq;
using Ludots.Core.Engine;
using Ludots.Core.Engine.Pacemaker;
using Ludots.Core.Persistence;
using Ludots.Core.Scripting;
using NUnit.Framework;

namespace Ludots.Tests.Persistence;

/// <summary>
/// Determinism measurement guard: world digests are only meaningful if a world that received no
/// input yields identical digests on repeated captures. Wall-clock diagnostics fields (render
/// interpolation alpha, frame timings, stopwatch-measured physics update time) must stay out of the
/// serialized payload — this test exists so that mistake cannot land silently again (#1311).
/// </summary>
public sealed class WorldDigestStabilityTests
{
    [Test]
    public void StaticWorldYieldsIdenticalDigestsAcrossCaptures()
    {
        using GameEngine engine = CreateInitializedEngine();
        UseTurnBasedPacemaker(engine);
        RunFixedSteps(engine, 3);

        string digestA = CaptureDigest(engine);
        string digestB = CaptureDigest(engine);

        Assert.That(digestB, Is.EqualTo(digestA), "second capture of an untouched world must match the first");
    }


    // Row-sorted digest lens (same as SaveContinuationTrace): raw blob bytes are not stable across
    // serialize invocations, so per-entity/per-component sorted rows are the only meaningful basis.
    private static string CaptureDigest(GameEngine engine)
    {
        LudotsBinaryWorldSerializer serializer = LudotsPersistenceSerializerFactory.Create(engine);
        byte[] worldBytes = serializer.Serialize(engine.World);
        using var canonical = serializer.Deserialize(worldBytes);
        SaveEntityWorldIdNormalizer.Normalize(canonical, 0);
        return RowDigest(canonical);
    }

    private static string RowDigest(Arch.Core.World world)
    {
        var options = SaveContinuationTrace.CreateComponentSerializerOptions();
        var rows = new List<string>();
        world.Query(in Arch.Core.QueryDescription.Null, entity =>
        {
            Arch.Core.Signature signature = world.GetSignature(entity);
            var componentRows = new List<string>(signature.Components.Length);
            foreach (Arch.Core.ComponentType componentType in signature.Components)
            {
                Type type = componentType.Type;
                object? component = world.Get(entity, componentType);
                componentRows.Add(component == null
                    ? $"{type.FullName ?? type.Name}=<null>"
                    : $"{type.FullName ?? type.Name}={Convert.ToHexString(MessagePack.MessagePackSerializer.Serialize(type, component, options))}");
            }

            componentRows.Sort(StringComparer.Ordinal);
            rows.Add($"{entity.Id}:{entity.Version}|{string.Join("|", componentRows)}");
        });

        rows.Sort(StringComparer.Ordinal);
        return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(
            System.Text.Encoding.UTF8.GetBytes(string.Join("\n", rows))))[..16];
    }

    private static void RunFixedSteps(GameEngine engine, int count)
    {
        var pacemaker = (TurnBasedPacemaker)engine.Pacemaker;
        for (int i = 0; i < count; i++)
        {
            pacemaker.Step();
            engine.Tick(0.05f);
        }
    }

    private static void UseTurnBasedPacemaker(GameEngine engine)
    {
        engine.Pacemaker = new TurnBasedPacemaker();
        engine.SimulationBudgetMsPerFrame = int.MaxValue;
        engine.SimulationMaxSlicesPerLogicFrame = 1000;
        engine.Start();
    }

    private static GameEngine CreateInitializedEngine()
    {
        string? dir = TestContext.CurrentContext.TestDirectory;
        while (!string.IsNullOrEmpty(dir))
        {
            string gitPath = Path.Combine(dir, ".git");
            if ((Directory.Exists(gitPath) || File.Exists(gitPath)) &&
                Directory.Exists(Path.Combine(dir, "src")) &&
                Directory.Exists(Path.Combine(dir, "mods")))
            {
                break;
            }

            dir = Directory.GetParent(dir)?.FullName;
        }

        var engine = new GameEngine();
        engine.InitializeWithConfigPipeline(
            RepoModPaths.ResolveExplicit(dir!, new[] { "LudotsCoreMod" }),
            Path.Combine(dir!, "assets"));
        engine.LoadStartupMap();
        return engine;
    }
}
